import{_ as t,o as a,c as n,ao as o}from"./chunks/framework.ucUddl5u.js";const g=JSON.parse('{"title":"Updating and rollback","description":"","frontmatter":{},"headers":[],"relativePath":"guide/updating.md","filePath":"guide/updating.md","lastUpdated":null}'),i={name:"guide/updating.md"};function s(d,e,r,l,c,h){return a(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="updating" tabindex="-1">Updating and rollback <a class="header-anchor" href="#updating" aria-label="Permalink to &quot;Updating and rollback {#updating}&quot;">​</a></h1><p>Updating a release install is one command. On a <code>--local</code> install and on Windows, an update whose frontend crash-loops right after applying is rolled back automatically.</p><p>Two mechanisms complement rather than compete (release installs only — <strong>source builds are stamped <code>-dev</code> and never self-update</strong>; they update by <code>git pull</code> + rebuild):</p><table tabindex="0"><thead><tr><th style="text-align:right;">Mechanism</th><th style="text-align:right;">What it does</th><th style="text-align:right;">What you do</th></tr></thead><tbody><tr><td style="text-align:right;"><strong>Built-in update check</strong></td><td style="text-align:right;">The backend checks GitHub for new releases (daily and on demand, plain HTTPS, no GitHub auth), <strong>notifies the frontend</strong>, and prepares the whole new version in the background: binaries, a tag-pinned checkout and instantiated Julia environments, verified against the release&#39;s <code>SHA256SUMS</code>. The staged version is applied at the next launch (or daemon restart) as an offline switch, with the previous version kept for rollback.</td><td style="text-align:right;">Nothing — you&#39;ll see the notice; relaunch when convenient.</td></tr><tr><td style="text-align:right;"><strong>Re-running the installer</strong></td><td style="text-align:right;">The <strong>complete</strong> update in one command: new binaries <em>and</em> the repo checkout moved to the new tag <em>and</em> Julia envs re-instantiated, atomically. It is also what migrates a pre-0.6 install onto the auto-update layout.</td><td style="text-align:right;"><code>curl -fsSL …/install.sh | bash -s -- &lt;your-role&gt;</code> (same command as install; add <code>--version vX.Y.Z</code> to pin).</td></tr></tbody></table><p><strong>When in doubt: re-run the installer.</strong> It is idempotent and moves everything together. With an agent, say:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Update Ship of Tools: fetch https://raw.githubusercontent.com/kalidke/ship-of-tools/main/docs/INSTALL-AGENT.md and follow it. If this machine runs a source build, replace it with a release install.</span></span></code></pre></div><p><code>SOT_UPDATE_MODE</code> controls the built-in check: <code>notify</code> (the default) stages and applies at the next launch, <code>off</code> disables it, and <code>auto</code> additionally restarts the backend to apply once no frontend is attached. That restarts REPLs and kernels, so their in-memory state is lost, which is why it is opt-in; agent sessions survive it.</p><p>On <strong>Windows</strong> the frontend runs the same check itself, since there is no local backend to do it, and <code>launch-sot.ps1</code> applies the staged update at the next launch through <code>scripts\\sot-apply.ps1</code>: the same verification and rollback, and a new build that crashes within 10 seconds of its first launch is reverted automatically.</p><p>On update the installer swaps binaries while keeping <code>.prev</code> copies, fetches tags in <code>$PREFIX/repo/current</code>, checks out the requested tag, <strong>refuses to move a dirty checkout</strong> (commit/stash/revert first — the checkout is read-only by convention), and verifies <code>HEAD</code> equals the tag&#39;s recorded commit, so a moved tag or half-checkout fails at update time, not at first use.</p><h2 id="Pinning-and-going-back" tabindex="-1">Pinning and going back <a class="header-anchor" href="#Pinning-and-going-back" aria-label="Permalink to &quot;Pinning and going back {#Pinning-and-going-back}&quot;">​</a></h2><ul><li><p><strong>Pin a release.</strong> Add <code>--version vX.Y.Z</code> to the install command to move to (or stay on) a specific tag; the same flag moves you <em>back</em> to an older tag.</p></li><li><p><strong>Automatic rollback.</strong> Applying a staged update is an offline pointer flip done by <code>sot-apply</code>, which records the previous install as <em>last good</em>. The <code>--local</code> launcher runs <code>sot-apply --rollback</code> if the frontend exits with an error within 10 seconds twice in the 30 minutes after an update; Windows does the same through <code>launch-sot.ps1</code>. A <code>--backend</code> (frontend-only) install on Linux or macOS does not roll back on its own: re-run the installer with <code>--version</code> to go back.</p></li><li><p><strong>Keep the checkout clean.</strong> The installed checkout under <code>$PREFIX/repo/current</code> is the manual and the resource tree. Updates refuse to move a dirty tree, so leave it read-only.</p></li></ul>',11)])])}const u=t(i,[["render",s]]);export{g as __pageData,u as default};
